import React, { useState, useEffect, useContext } from "react";
import { useAuthorize } from "../context/hook/useAuthorization"; // Hook to access user authorization context

import '../styles/courses.css'; // Course-specific styles
import '../styles/surveys.css'; // Survey-specific styles
import 'animate.css'; // Animations for UI elements

import * as MdIcons from "react-icons/md"; // Icons for UI decoration
import { FiMinimize2 } from "react-icons/fi"; // Icon for minimizing elements
import survey_icon from './Images/Survey/survey-card-img2.jpg'; // Icon for surveys
import no_record_icon from './Images/Record/no-record-img.png'; // Icon when no records are available

import NavMenu from "./SharedComponents/navMenu"; // Shared navigation menu
import LoadingIcon from "./SharedComponents/loading"; // Loading indicator component

import Swal from "sweetalert2"; // Library for better alert dialogs

import { SocketContext } from "../context/socket"; // Context for managing real-time socket interactions
import 'react-tooltip/dist/react-tooltip.css'; // Styles for tooltips
import { Tooltip } from 'react-tooltip'; // Tooltip component for additional information display

const Surveys = (props) => {
    const { userAccount } = useAuthorize(); // Access user account details from context

    const socket = useContext(SocketContext); // Socket context for real-time data updates

    const [surveys, setSurveys] = useState(null); // State to store survey data
    const [surveysExist, setExist] = useState(true); // State to check if surveys exist

    const [title, setTitle] = useState(''); // State for new survey title
    const [description, setDescript] = useState(''); // State for new survey description
    const [error, setError] = useState(''); // State for managing errors
    const [isLoading, setIsLoading] = useState(false); // State for loading indicator
    const [isFetching, setFetching] = useState(true); // State to manage initial data fetch

    const [surveyId, setSurveyId] = useState(''); // State to manage active survey ID
    const [showResponse, setShowResponse] = useState(false); // State to toggle response visibility

    const [blankFields, setBlankFields] = useState([]); // State for highlighting empty fields on form submission
    const [commentBlank, setCommentBlank] = useState([]); // State for highlighting empty comment field

    const [comment, setComment] = useState(''); // State for storing user comments
    const [commentError, setCommentError] = useState(''); // State for managing comment errors

// useEffect hook that runs once on component mount, or when userAccount changes.
useEffect(() => {
    // Function to fetch survey data from the backend.
    const fetchSurveys = async () => {
        setFetching(true);  // Start loading indicator.
        const result = await fetch('/api/survey/', {
            headers: {
                'Authorization': `Bearer ${userAccount.userToken}`  // Use JWT from userAccount for authorization.
            }
        });

        // Parsing the JSON result into an array of survey objects.
        const resultJson = await result.json();

        // Check if the HTTP request was successful.
        if (result.ok) {
            // Determine which surveys to display based on user's role.
            if (userAccount.occupation === 'admin') {
                // Admins see all surveys.
                setSurveys(resultJson);
                setExist(resultJson.length !== 0);  // Update to true if there are any surveys.
            } else {
                // Non-admin users only see surveys marked as visible.
                let visibleSurveys = resultJson.filter(survey => survey.visibility === 'true');
                setSurveys(visibleSurveys);
                setExist(visibleSurveys.length > 0);  // Update to true if there are any visible surveys.
            }
        } else {
            // Handle errors if the fetch was unsuccessful.
            setExist(false);  // Set to false since no surveys could be fetched.
        }

        setFetching(false);  // Stop loading indicator.
    };

    // Only run the fetching process if there's a logged-in user.
    if (userAccount) {
        fetchSurveys();
        // Emit an event via socket to potentially trigger other real-time updates.
        socket.emit('courses', socket.id);
    }

}, [userAccount]); // This effect depends on the `userAccount` and runs again if it changes.


    useEffect(()=>{
        socket.on('surveys', (newSurveyAll)=>{
            if(userAccount.occupation === 'admin')
            {
                setSurveys(newSurveyAll);
                if(newSurveyAll.length === 0){
                    setExist(false);
                }
                else{
                    setExist(true);
                }
            }
            else
            {
                let visibleSurveys = [];
                for(let i=0; i < newSurveyAll.length; i++)
                {
                    if(newSurveyAll[i].visibility === 'true')
                        visibleSurveys.push(newSurveyAll[i]);
                }
                setSurveys(visibleSurveys);
                if(visibleSurveys.length === 0){
                    setExist(false);
                }
                else{
                    setExist(true);
                }
            }
        })

    }, []);

    const handleNewSurvey = async (e) => {

        // Prevents default action of page refresh on form submission
        e.preventDefault();

        if(!userAccount)
        {
            setError('You are not logged in');
            return;
        }
        else if(userAccount.occupation !== 'admin')
        {
            setError('You are not an admin');
            return;
        }

        setIsLoading(true);

        if((!title || title.trim().length === 0) || (!description || description.trim().length === 0)){
            setBlankFields([]);
            setError('Please fill out all the fields');
            let emptyfields = []
            if(!title || title.trim().length === 0){
                emptyfields.push('Name');
            }
            if(!description || description.trim().length === 0){
                emptyfields.push('Location');
            }
            setBlankFields(emptyfields);
            setIsLoading(false);
            return;
        }

        const newSurvey = {title, description};

        const result = await fetch('/api/survey/', {
            method: 'POST',
            body: JSON.stringify(newSurvey),
            headers: {
                'Content-Type': 'application/json',
                'Authorization': `Bearer ${userAccount.userToken}`
            }
        });
        
        const resultJson = await result.json();

        if (result.ok)
        {
            setError(null);
            setBlankFields([]);
            setTitle('');
            setDescript('');
            console.log("New WorkSpace added: ",resultJson);
            Swal.fire({
                icon: "success",
                title: "New WorkSpace Added!",
                confirmButtonColor: "#1d578a",
            });
            setIsLoading(false);
        }
        else
        {
            setError(resultJson.error);
            if(resultJson.errorFields)
            {
                setBlankFields(resultJson.errorFields);
            }
            else
            {
                setBlankFields([]);
            }
            setIsLoading(false);
        }
        
    }

    const handleDeleteSurvey = async (id) => {
        if(!userAccount)
            return;
        else if(userAccount.occupation !== 'admin')
            return;

        let cancelOperation = false;

        await Swal.fire({
            title: "Are you sure?",
            text: "Delete this WorkSpace?",
            icon: "warning",
            showCancelButton: true,
            confirmButtonColor: "#d33",
            cancelButtonColor: "#1d578a",
            confirmButtonText: "Yes",
            }).then((result) => {
            if (!result.isConfirmed) {
                cancelOperation = true;
            }
        });

        if (cancelOperation) {return;}

        const result = await fetch('/api/survey/' + id, {
            method: 'DELETE',
            headers: {
                'Authorization': `Bearer ${userAccount.userToken}`
            }
        })

        const resultJson = await result.json();

        if (result.ok)
        {
            console.log("WorkSpace deleted: ",resultJson);
            Swal.fire({
                icon: "success",
                title: "WorkSpace deleted!",
                confirmButtonColor: "#1d578a",
            });
        }
        else
        {
            console.log(resultJson.error)
        }
    }

    const handleVisibilityTrue = async (id) => {
        if(!userAccount)
            return;
        else if(userAccount.occupation !== 'admin')
            return;

        let cancelOperation = false;

        await Swal.fire({
            title: "Are you sure?",
            text: "Users will be able to see this WorkSpace!",
            icon: "warning",
            showCancelButton: true,
            confirmButtonColor: "#d33",
            cancelButtonColor: "#1d578a",
            confirmButtonText: "Yes",
            }).then((result) => {
            if (!result.isConfirmed) {
                cancelOperation = true;
            }
        });

        if (cancelOperation) {return;}

        const result = await fetch('/api/survey/' + id, {
            method: 'PATCH',
            body: JSON.stringify({visibility : 'true'}),
            headers: {
                'Content-Type': 'application/json',
                'Authorization': `Bearer ${userAccount.userToken}`
            }
        })

        const resultJson = await result.json();

        if (result.ok)
        {
            console.log("WorkSpace visible: ",resultJson);
            Swal.fire({
                icon: "info",
                title: "WorkSpace is now visible to users!",
                confirmButtonColor: "#1d578a",
            });
        }
        else
        {
            console.log(resultJson.error)
        }
    }

    const handleVisibilityFalse = async (id) => {
        if(!userAccount)
            return;
        else if(userAccount.occupation !== 'admin')
            return;

        let cancelOperation = false;

        await Swal.fire({
            title: "Are you sure?",
            text: "Users will not be able to see this WorkSpace!",
            icon: "warning",
            showCancelButton: true,
            confirmButtonColor: "#d33",
            cancelButtonColor: "#1d578a",
            confirmButtonText: "Yes",
            }).then((result) => {
            if (!result.isConfirmed) {
                cancelOperation = true;
            }
        });

        if (cancelOperation) {return;}

        const result = await fetch('/api/survey/' + id, {
            method: 'PATCH',
            body: JSON.stringify({visibility : 'false'}),
            headers: {
                'Content-Type': 'application/json',
                'Authorization': `Bearer ${userAccount.userToken}`
            }
        })

        const resultJson = await result.json();

        if (result.ok)
        {
            console.log("WorkSpace visible: ",resultJson);
            Swal.fire({
                icon: "info",
                title: "WorkSpace is no longer visible to the users!",
                confirmButtonColor: "#1d578a",
            });
        }
        else
        {
            console.log(resultJson.error);
        }
    }

    const getResponseEmail = (item) => {
        return item.split(';')[0];
    }

    const getResponseComment = (item) => {
        const components = item.split(';')
        let response = '';
        for (let i = 1; i < components.length; i++){
            response = response + components[i];
        }
        return response
    }

    const displayResponse = (id) => {
        setShowResponse(true);
        setSurveyId(id);
        setComment('');
        setCommentError('');
        setCommentBlank('')
    }

    const removeResponse = (id) => {
        setShowResponse(false);
        setSurveyId(null);
        setComment('');
        setCommentError('');
        setCommentBlank('')
    }

    const handleAddComment = async(e) => {

        // Prevents default action of page refresh on form submission
        e.preventDefault();

        if(!userAccount)
        {
            setError('You are not logged in');
            return;
        }
        else if(userAccount.occupation !== 'employee')
        {
            setError('You are not an employee');
            return;
        }

        setIsLoading(true);

        if(!comment || (comment && !comment.trim())){
            setCommentError('Please fill out the comment field');
            setCommentBlank(['Response']);
            setIsLoading(false);
            return;
        }

        const result = await fetch('/api/survey/comment/' + surveyId, {
            method: 'PATCH',
            body: JSON.stringify({response: comment}),
            headers: {
                'Content-Type': 'application/json',
                'Authorization': `Bearer ${userAccount.userToken}`
            }
        });

        const resultJson = await result.json();
        if (result.ok)
        {
            setComment('');
            setCommentError('');
            setCommentBlank([]);
            setIsLoading(false);
        }
        else{
            setCommentError(resultJson.error);
            if(resultJson.errorFields)
            {
                setCommentBlank(resultJson.errorFields);
            }
            else
            {
                setCommentBlank([]);
            }
            setIsLoading(false);
        }

    }

    return (   
        <div className="coursespage">

            {/* Main Nav Bar */}
            <NavMenu isAdmin={userAccount.occupation === 'admin' ? true : false} breadcrum="Surveys" pagePath="/surveys"/>

            {/* Course Add Form */}
            <div className={userAccount.occupation === 'admin' ? 'course-management' : 'course-management course-access'}>
                {userAccount && userAccount.occupation === 'admin' && 
                    <div className="course-add-form survey-add-form">
                        <form onSubmit={handleNewSurvey}>
                            <h1>Add A New Workspace</h1>
                            <div className="course-form-unit">
                                <label>Workspace Name<span className="form-required">*</span></label>
                                <input 
                                    type="text" 
                                    onChange={(e) => setTitle(e.target.value)} 
                                    value={title} 
                                    className={blankFields.includes('Title') ? 'empty-error' : ''} 
                                />
                            </div>
                            <div className="course-form-unit">
                                <label>Workspace location<span className="form-required">*</span></label>
                                <input 
                                    type="text" 
                                    onChange={(e) => setDescript(e.target.value)} 
                                    value={description} 
                                    className={blankFields.includes('Description') ? 'empty-error' : ''} 
                                />
                            </div>
                            <button disabled={isLoading}>Add WorkSpace</button>
                            {error && <div className="error">{error}</div>}
                        </form>
                    </div>
                }

                {/* Course Cards */}
                <div className="courses">
                    {isFetching && <div className={userAccount.occupation === 'admin' ? 'loading-spinner-wrapper-surveys' : 'loading-spinner-wrapper-courses-view'}><LoadingIcon  /></div>}
                    {!isFetching && !surveysExist &&
                        <div className={userAccount.occupation === 'admin' ? 'no-courses animate__animated animate__fadeInUp' : 'no-courses no-courses-view  animate__animated animate__fadeInUp'}>
                            <img src={no_record_icon} alt="Record None" />
                            <h2>{userAccount.occupation === 'admin' ? 'No WorkSpace Added' : 'No WorkSpace Available'}</h2>
                        </div>
                    }
                    {!isFetching && surveysExist && surveys && surveys.map((survey) => (
                        <div key={survey._id} className="course-card animate__animated animate__fadeInUp">
                            {userAccount && userAccount.occupation === 'admin' && 
                                <div className="survey-card-delete-wrapper">
                                    {survey.visibility === 'true' && <MdIcons.MdPauseCircleOutline data-tooltip-id="survey" data-tooltip-content="Hide survey from employees"  className="course-card-delete-icon survey-visibility-pause" onClick={()=>handleVisibilityFalse(survey._id)} />}
                                    {survey.visibility === 'false' && <MdIcons.MdOutlinePlayCircleOutline data-tooltip-id="survey" data-tooltip-content="Show survey to employees" className="course-card-delete-icon survey-visibility-play" onClick={()=>handleVisibilityTrue(survey._id)} />}
                                    <MdIcons.MdDelete data-tooltip-id="survey" data-tooltip-content="Delete survey" className="course-card-delete-icon" onClick={()=>handleDeleteSurvey(survey._id)} />
                                    <Tooltip id="survey" place="left" style={{ backgroundColor: "#cbd6e2", color: "#222", fontSize: "13px", fontWeight: "normal" }}/>
                                </div>
                            }
                            <ul className="course-card-content-wrapper">
                                <li>
                                    <img src={survey_icon} alt="Course"/>
                                </li>
                                <li>
                                    <h2 className="make-blue">{survey.title}</h2>
                                    <p>{survey.description}</p>
                                </li>
                            </ul>
                            {(surveyId !== survey._id || !showResponse) && <div className="course-card-link-wrapper">
                                <div className="survey-response-selector" onClick={()=>displayResponse(survey._id)}>{userAccount.occupation === 'admin' ? 'View Response' : 'Comment'}</div>
                            </div>}
                            {surveyId === survey._id && showResponse &&
                                <div> 
                                    <ul className="survey-response-wrapper">
                                        <div className="response-heading">Response<FiMinimize2 className="minimize" onClick={removeResponse}/></div>
                                        {survey.responses.length === 0 ? <div className="no-response-wrapper">No Response</div> :
                                            survey.responses && survey.responses.map((item, index) => (
                                                <li className="survey-response" key={index}>
                                                    <div className="response-email">{getResponseEmail(item)}</div>
                                                    <div className="response-comment">{getResponseComment(item)}</div>
                                                </li>
                                            ))
                                        }
                                    </ul>
                                    {userAccount && userAccount.occupation === 'employee' && 
                                        <form className="comment-form" onSubmit={handleAddComment}>
                                            <div className="comment-form-unit">
                                                <input 
                                                    placeholder="Add Comment"
                                                    type="text" 
                                                    onChange={(e) => setComment(e.target.value)} 
                                                    value={comment} 
                                                    className={commentBlank.includes('Response') ? 'empty-error' : ''} 
                                                />
                                                <button disabled={isLoading}>Add</button>
                                            </div>
                                            {commentError && <div className="comment-error">{commentError}</div>}
                                        </form>
                                    }
                                </div> 
                            }
                        </div>
                    ))}
                </div>
            </div>
        </div>
    )

}

export default Surveys
